import Empty from "@marko-ui/shadcn/ui/empty/empty.marko";
import EmptyHeader from "@marko-ui/shadcn/ui/empty/header.marko";
import EmptyMedia from "@marko-ui/shadcn/ui/empty/media.marko";
import EmptyTitle from "@marko-ui/shadcn/ui/empty/title.marko";
import EmptyDescription from "@marko-ui/shadcn/ui/empty/description.marko";
import EmptyContent from "@marko-ui/shadcn/ui/empty/content.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

<Empty class="border border-dashed">
  <EmptyHeader>
    <EmptyMedia variant="icon">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z"/>
      </svg>
    </EmptyMedia>
    <EmptyTitle>Cloud storage empty</EmptyTitle>
    <EmptyDescription>Upload files to your cloud storage to access them anywhere.</EmptyDescription>
  </EmptyHeader>
  <EmptyContent>
    <Button type="button" variant="outline" size="sm">Upload files</Button>
  </EmptyContent>
</Empty>

import Empty from "@marko-ui/shadcn/ui/empty/empty.marko";
import EmptyHeader from "@marko-ui/shadcn/ui/empty/header.marko";
import EmptyMedia from "@marko-ui/shadcn/ui/empty/media.marko";
import EmptyTitle from "@marko-ui/shadcn/ui/empty/title.marko";
import EmptyDescription from "@marko-ui/shadcn/ui/empty/description.marko";
import EmptyContent from "@marko-ui/shadcn/ui/empty/content.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Avatar from "@marko-ui/shadcn/ui/avatar/avatar.marko";

<Empty>
  <EmptyHeader>
    <EmptyMedia>
      <Avatar class="size-12" src="https://github.com/shadcn.png" alt="@shadcn" fallback="LR"/>
    </EmptyMedia>
    <EmptyTitle>User offline</EmptyTitle>
    <EmptyDescription>
      This user is currently offline. You can leave a message to notify them or try again later.
    </EmptyDescription>
  </EmptyHeader>
  <EmptyContent>
    <Button type="button" size="sm">Leave message</Button>
  </EmptyContent>
</Empty>
